 2: import {
 3:   applyDamage,
 4:   applyHealPickup,
 5:   createInitialPlayerState,
 6:   tickShieldRecovery
 7: } from "./playerState";
 8: 
 9: describe("playerState survival rules", () => {
10:   it("createInitialPlayerState returns expected defaults", () => {
11:     const p = createInitialPlayerState();
12: 
13:     expect(p.maxHealth).toBe(100);
14:     expect(p.health).toBe(100);
15:     expect(p.maxShield).toBe(60);
16:     expect(p.shield).toBe(60);
17:     expect(p.lastDamageAt).toBe(-Infinity);
18:     expect(p.shieldRecoveryDelayMs).toBe(1000);
19:     expect(p.shieldRecoveryPerSecond).toBe(18);
20:   });
21: 
22:   it("routes incoming damage to shield before health", () => {
23:     const player = createInitialPlayerState();
24: 
25:     const damaged = applyDamage(player, 30, 1000);
26: 
27:     expect(damaged.shield).toBe(30);
28:     expect(damaged.health).toBe(100);
29:     expect(damaged.lastDamageAt).toBe(1000);
30:   });
31: 
32:   it("overflow damage spills from shield to health", () => {
33:     const player = createInitialPlayerState();
34: 
35:     const damaged = applyDamage(player, 70, 1000);
36: 
37:     expect(damaged.shield).toBe(0);
38:     expect(damaged.health).toBe(90);
39:   });
40: 
41:   it("starts shield recovery only after the recovery delay", () => {
42:     // First take enough damage to ensure shield is below max so recovery has room.
43:     const player = applyDamage(createInitialPlayerState(), 50, 1000);
44:     expect(player.shield).toBe(10);
45: 
46:     const tooEarly = tickShieldRecovery(player, 1500);
47:     expect(tooEarly.shield).toBe(10);
48: 
49:     const recovered = tickShieldRecovery(player, 2500);
50:     expect(recovered.shield).toBeGreaterThan(10);
51:     expect(recovered.shield).toBeLessThanOrEqual(60);
52:   });
53: 
54:   it("heals health with pickups without exceeding max health", () => {
55:     const player = applyDamage(createInitialPlayerState(), 90, 1000);
56:     expect(player.health).toBe(70);
57: 
58:     const healed = applyHealPickup(player, 20);
59:     expect(healed.health).toBe(90);
60: 
61:     const clamped = applyHealPickup(healed, 999);
62:     expect(clamped.health).toBe(100);
63:   });
64: });
